 {panel==='cart'&&<Modal title="Coșul tău" onClose={()=>setPanel(null)}><div className="panel-body"><p className="eyebrow dark">{step===3?'TEST SALVAT':'POFTA TA, ÎN COȘ'}</p><h2>{step===3?'Comanda ta de test.':step===2?'Aproape de ceva bun.':'Coșul tău.'}</h2>{step<3&&<div className="steps"><span className={step===1?'current':''}>1. Preparatele</span><ArrowRight size={14}/><span className={step===2?'current':''}>2. Datele tale</span></div>}{step===1&&(!count?<div className="empty"><ShoppingBag size={40}/><h3>Ceva bun își așteaptă locul.</h3><p>Alege din meniu și adaugă preparatele preferate.</p><button className="button dark-button" onClick={()=>{setPanel(null);document.getElementById('meniu')?.scrollIntoView({behavior:'smooth'})}}>Descoperă meniul <ArrowRight size={18}/></button></div>:<><div className="cart-lines">{lines.map(d=><div className="cart-line" key={d.id}><div className="cart-thumbnail"><DishPhoto dish={d} sizes="65px"/></div><div><h4>{d.name}</h4><p>{d.weight} · {money(d.price)} / porție</p><div className="quantity compact"><button aria-label={'Scade '+d.name} onClick={()=>change(d.id,-1)}><Minus size={15}/></button><span>{cart[d.id]}</span><button aria-label={'Crește '+d.name} onClick={()=>change(d.id,1)}><Plus size={15}/></button></div></div><div><strong>{money(d.price*cart[d.id])}</strong><button className="remove" aria-label={'Elimină '+d.name} onClick={()=>setCart(c=>{const n={...c};delete n[d.id];return n})}><Trash2 size={16}/></button></div></div>)}</div><div className="fulfillment"><button className={mode==='ridicare'?'active':''} onClick={()=>setMode('ridicare')}><Package size={20}/>Ridicare</button><button className={mode==='livrare'?'active':''} onClick={()=>setMode('livrare')}><Truck size={20}/>Livrare</button></div><div className="promo"><input aria-label="Cod promoțional" placeholder="Ai un cod promoțional?" value={promo} onChange={e=>{setPromo(e.target.value);setPromoMessage('')}}/><button disabled={!promo.trim()} onClick={()=>setPromoMessage('Nu există o campanie activă în versiunea de test.')}>Aplică</button></div>{promoMessage&&<p className="form-note">{promoMessage}</p>}<div className="total-row"><span>Total preparate</span><strong>{money(total)}</strong></div>{mode==='livrare'&&<p className="form-note">Zona, taxa și timpul de livrare urmează să fie confirmate cu restaurantul.</p>}<p className="test-note">Poți testa întregul flux. Nu se trimite o comandă reală și nu se încasează bani.</p><button className="button dark-button full" onClick={()=>{setStep(2);setError('')}}>Continuă <ArrowRight size={18}/></button></>)}{step===2&&<form onSubmit={submitOrder}><button type="button" className="underlink" onClick={()=>setStep(1)}>← Înapoi la coș</button><div className="form-grid"><label>Nume<input name="name" required minLength={2} maxLength={80} autoComplete="name" placeholder="Numele tău"/></label><label>Telefon<input name="phone" type="tel" required pattern="\+?[0-9 ()-]{9,20}" autoComplete="tel" placeholder="07xx xxx xxx"/></label>{mode==='livrare'&&<label className="span-2">Adresa de livrare<input name="address" required minLength={5} maxLength={300} autoComplete="street-address" placeholder="Stradă, număr, bloc, localitate"/></label>}<label className="span-2">Observații <span>(opțional)</span><textarea name="notes" maxLength={500} placeholder="Ce ai vrea să știm despre comanda ta?"/></label></div><div className="payment"><span><ShoppingBag size={18}/>{mode==='livrare'?'Livrare':'Ridicare din restaurant'}</span><span>Plată la primire · simulare</span></div><div className="total-row"><span>Total preparate</span><strong>{money(total)}</strong></div><p className="test-note">Simulare locală. Folosește date fictive; nimic nu se trimite restaurantului.</p>{error&&<p className="form-error" role="alert">{error}</p>}<button className="button dark-button full" disabled={busy||!count}>{busy?'Se salvează…':'Salvează comanda de test'}<ArrowRight size={18}/></button></form>}{step===3&&order&&<><div className="success-icon"><Check/></div><p>Testul a fost salvat. Nicio comandă nu a fost trimisă restaurantului.</p><div className="order-reference"><span>COMANDA #{order.id.slice(0,8).toUpperCase()}</span><strong>{money(order.total/100)}</strong></div><div className="tracking">{statuses.map((s,i)=><div className={statuses.indexOf(order.status)>=i?'done':''} key={s}><span>{statuses.indexOf(order.status)>i?<Check size={13}/>:i+1}</span><p>{s}</p></div>)}</div>{order.status==='anulată'&&<p className="form-error">Test anulat.</p>}<p className="form-note">Statusul demonstrativ avansează automat și se actualizează la 10 secunde.</p><button className="button dark-button full" onClick={openOrders}>Vezi testele sesiunii <ArrowUpRight size={18}/></button><a className="button outline-light full" href="tel:0756021501"><Phone size={18}/>Sună restaurantul</a></>}</div></Modal>}
 {panel==='reservation'&&<Modal title={reserveKind==='masă'?'Rezervă o masă':'Evenimentul tău'} onClose={()=>setPanel(null)}><div className="panel-body"><p className="eyebrow dark">UN MOMENT PENTRU TINE</p><h2>{reserveKind==='masă'?'Ne vedem la masă?':'Ce sărbătorim?'}</h2>{reserved?<><div className="success-icon"><Check/></div><h3>Cererea de test a fost simulată.</h3><p>Nu este o rezervare confirmată. Pentru o rezervare reală, contactează Casa Mia.</p><a className="button dark-button full" href={reserveKind==='masă'?'tel:0756021501':'tel:0761736599'}><Phone size={18}/>{reserveKind==='masă'?'0756 021 501':'0761 736 599'}</a></>:<form onSubmit={submitReservation}><div className="form-grid"><label>Nume<input name="name" required minLength={2} maxLength={80} autoComplete="name" placeholder="Numele tău"/></label><label>Telefon<input name="phone" type="tel" required pattern="\+?[0-9 ()-]{9,20}" autoComplete="tel" placeholder="07xx xxx xxx"/></label><label>Data<input name="date" type="date" min={today} required/></label><label>Ora<input name="time" type="time" required defaultValue="19:00"/></label><label className="span-2">Număr de persoane<input name="guests" type="number" min={1} max={reserveKind==='masă'?20:200} defaultValue={2} required/></label><label className="span-2">{reserveKind==='masă'?'Observații (opțional)':'Spune-ne despre eveniment'}<textarea name="notes" maxLength={1000} placeholder={reserveKind==='masă'?'O ocazie specială, preferințe…':'Ocazia, numărul de invitați, ce ai în minte…'}/></label></div><p className="test-note">Formular demonstrativ. Nu rezervă o masă și nu trimite cererea restaurantului.</p>{error&&<p className="form-error" role="alert">{error}</p>}<button className="button dark-button full" disabled={busy}>{busy?'Se salvează…':'Salvează cererea de test'}<ArrowRight size={18}/></button><a className="button outline-light full" href={reserveKind==='masă'?'tel:0756021501':'tel:0761736599'}><Phone size={17}/>Sună pentru o rezervare reală</a></form>}</div></Modal>}
 {panel==='orders'&&<Modal title="Comenzile mele de test" onClose={()=>setPanel(null)}><div className="panel-body"><p className="eyebrow dark">SIMULATE ÎN ACEASTĂ SESIUNE</p><h2>Comenzile de test.</h2>{busy?<p>Se încarcă…</p>:error?<p role="alert" className="form-error">{error}</p>:history.length?history.map(o=><button className="history-line" key={o.id} onClick={()=>{setOrder(o);setStep(3);setPanel('cart')}}><div><strong>#{o.id.slice(0,8).toUpperCase()}</strong><p>{o.createdAt&&new Date(o.createdAt).toLocaleString('ro-RO')} · {o.status}</p></div><span>{money(o.total/100)} <ChevronRight size={18}/></span></button>):<div className="empty"><ShoppingBag size={32}/><p>Încă nu ai comenzi de test salvate.</p><button className="button dark-button" onClick={()=>setPanel(null)}>Înapoi la meniu</button></div>}</div></Modal>}
 {panel==='event-menus'&&<Modal title="Meniuri cununie, botez și parastas" onClose={()=>setPanel(null)} wide><div className="event-menu-dialog"><EventMenus key={eventOccasion} initialOccasion={eventOccasion} compact onOriginal={openOriginal}/></div></Modal>}
 {panel==='gallery'&&<Modal title={originalMenus[originalKind].title} onClose={()=>setPanel(null)} wide><OriginalMenuGallery kind={originalKind} onChange={setOriginalKind}/></Modal>}
 </>;
}
